const $=s=>document.querySelector(s), money=n=>'Rs. '+n.toLocaleString('en-PK'),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
