function saved(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}let bag=saved('se-bag',[]),wish=saved('se-wish',[]),orders=saved('se-orders',[]),selected=null,homeTab='All',filterState={condition:'All',size:'All',price:'All'},sort='featured',lastFocus;
function persist(){localStorage.setItem('se-bag',JSON.stringify(bag));localStorage.setItem('se-wish',JSON.stringify(wish));$('#count').textContent=bag.reduce((a,b)=>a+b.qty,0)}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2400)}
function card(p){return `<article class="product"><div class="product-image"><a href="#product/${p.id}" aria-label="View ${p.name}"><img loading="lazy" src="assets/${p.img}.png" alt="${p.name}"></a><span class="badge ${p.id%3===1?'lime':''}">${p.id%3===1?'FRESH FIND':p.condition.toUpperCase()}</span><button class="wish ${wish.includes(p.id)?'on':''}" onclick="toggleWish(${p.id},this)" aria-label="Save ${p.name}" aria-pressed="${wish.includes(p.id)}">${wish.includes(p.id)?'♥':'♡'}</button><button class="quick" onclick="quick(${p.id})" aria-label="Choose ${p.name}">+</button></div><div class="product-meta">${p.brand.toUpperCase()}</div><h3><a href="#product/${p.id}">${p.name}</a></h3><div class="price">${money(p.price)}<del>${money(p.old)}</del></div><div class="size-note">${p.sizes.length?'EU '+p.sizes.join(' · '):'One size'} <span style="float:right">${p.category}</span></div></article>`}
function toggleWish(id,b){wish=wish.includes(id)?wish.filter(x=>x!==id):[...wish,id];persist();if(b){b.textContent=wish.includes(id)?'♥':'♡';b.classList.toggle('on',wish.includes(id));b.setAttribute('aria-pressed',wish.includes(id))}if(location.hash==='#wishlist')render();toast(wish.includes(id)?'Saved to your wishlist':'Removed from wishlist')}
function home(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span> THE SECOND CHANCE COLLECTION</div><h1>Great shoes.<br><em>Better stories.</em></h1><p>Your next favourite pair already has a little history.<br>Discover carefully picked pre-loved finds, for less.</p><a class="btn" href="#shop">Find your pair <span>↗</span></a></div><div class="hero-art"><div class="hero-stamp">LESS WASTE<br>MORE STYLE<br>↗</div><img src="assets/hero.png" alt="White court sneaker"><div class="hero-label">A FRESH START. FROM THE GROUND UP.</div></div></section><div class="trust"><span>✓ Carefully checked pairs</span><span>↻ A more thoughtful way to shop</span><span>◇ Prices that feel good</span><span>↗ Made for your everyday</span></div><div class="wrap"><section class="section"><div class="section-head"><div><h2>Find your kind of sole.</h2><p>A little something for every step.</p></div><a class="text-link" href="#shop">Explore all ↗</a></div><div class="categories">${categories.map(([n,i])=>`<a class="category" href="#shop/${n}"><figure><img src="assets/${i}.png" alt="${n}" loading="lazy"></figure>${n}</a>`).join('')}</div></section><section class="section"><div class="section-head"><div><div class="eyebrow" style="margin-bottom:12px">JUST LANDED</div><h2>Fresh finds. First dibs.</h2><p>Good pairs don't stay for long.</p></div><a href="#shop" class="text-link">Shop new arrivals ↗</a></div><div class="tabs">${['All','Men','Women','Kids'].map(x=>`<button class="chip ${homeTab===x?'active':''}" onclick="homeTab='${x}';refreshHome()">${x==='All'?'All finds':x}</button>`).join('')}</div><div class="grid" id="home-products">${products.filter(p=>homeTab==='All'||p.category===homeTab).slice(0,4).map(card).join('')}</div></section><div class="editorial"><a href="#shop/Men"><img src="assets/editorial-men.jpg" alt="Casual footwear edit" loading="lazy"><div class="editorial-copy"><div class="eyebrow">THE MEN'S EDIT</div><h2>Everyday pairs.<br>Anything but<br>ordinary.</h2><span class="text-link">Discover the edit ↗</span></div></a><a href="#shop/Women"><img src="assets/editorial-women.jpg" alt="Women's footwear edit" loading="lazy"><div class="editorial-copy"><div class="eyebrow">THE WOMEN'S EDIT</div><h2>Your style.<br>Your next<br>great find.</h2><span class="text-link">Make it yours ↗</span></div></a></div><section class="section"><div class="section-head"><div><h2>Big names. Small footprints.</h2><p>Discover the brands you love in the reference collection.</p></div></div><div class="brand-strip"><a href="#shop/Sports">NIKE ↗</a><a href="#shop/Casual">allbirds</a><a href="#shop/Sports">adidas</a><a href="#shop/Orthopedic">On.</a><a href="#shop/Casual">SKECHERS</a></div></section><section class="section"><div class="section-head"><div><div class="eyebrow" style="margin-bottom:12px">THE GOOD DEAL EDIT</div><h2>Great finds under Rs. 3,000.</h2><p>More style. A little less spend.</p></div><a class="text-link" href="#shop/Under%203000">Shop the deals ↗</a></div><div class="grid">${products.filter(p=>p.price<3000).slice(0,4).map(card).join('')}</div></section></div><section class="manifesto"><div><div class="eyebrow" style="margin-bottom:15px">PRE-LOVED. RE-LOVED.</div><h2>A good pair deserves another chapter.</h2><p>Thoughtfully chosen. Ready for new adventures. Give great shoes a second chance, and make your next step a little lighter.</p></div><a class="btn" href="#shop">Shop a little differently ↗</a></section>`}
function refreshHome(){const y=scrollY;$('#app').innerHTML=home();scrollTo(0,y)}
function collection(cat='All',query=''){let list=products.filter(p=>cat==='All'||cat==='Sale'||(cat==='Under 3000'?p.price<3000:p.category===cat||p.type===cat));if(query)list=list.filter(p=>query.toLowerCase().split(/\s+/).every(q=>(p.name+' '+p.brand+' '+p.type+' '+p.category+' '+p.color).toLowerCase().split(/\s+/).some(word=>word===q||word.startsWith(q))));if(filterState.condition!=='All')list=list.filter(p=>p.condition===filterState.condition);if(filterState.size!=='All')list=list.filter(p=>p.sizes.includes(Number(filterState.size)));if(filterState.price==='under')list=list.filter(p=>p.price<3000);if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);if(sort==='new')list.reverse();if(sort==='discount')list.sort((a,b)=>(1-b.price/b.old)-(1-a.price/a.old));return `<div class="wrap"><div class="breadcrumb"><a href="#home">Home</a> / ${esc(query?'Search':cat==='All'?'All finds':cat)}</div><div class="collection-header"><div class="eyebrow" style="margin-bottom:15px">YOUR NEXT GREAT FIND</div><h1>${query?'Results for “'+esc(query)+'”':cat==='All'?'The complete edit.':esc(cat)+'.'}</h1><p>Carefully picked pairs. Ready for their next chapter.</p></div><div class="toolbar"><span>${list.length} finds · Sample inventory</span><button class="chip mobile-filter" onclick="$('.filters').classList.toggle('visible')">☷ Filters</button><select aria-label="Sort products" onchange="sort=this.value;rerender()">${[['featured','Featured'],['new','Newest first'],['low','Price: low to high'],['high','Price: high to low'],['discount','Biggest discount']].map(([v,t])=>`<option value="${v}" ${sort===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="shop-layout"><aside class="filters"><h4>CATEGORIES</h4>${['All',...categories.map(c=>c[0])].map(n=>`<a class="menu-link" style="padding:9px 0;font-size:12px;${cat===n?'font-weight:700':''}" href="#shop/${n}">${n==='All'?'All finds':n}</a>`).join('')}<h4 style="margin-top:25px">CONDITION</h4>${['All','Excellent','Very good','New'].map(n=>`<label><input type="radio" name="condition" ${filterState.condition===n?'checked':''} onchange="filterState.condition='${n}';rerender()">${n}</label>`).join('')}<h4 style="margin-top:25px">EU SIZE</h4><select aria-label="Filter by size" onchange="filterState.size=this.value;rerender()">${['All',29,30,31,32,37,38,39,40,41,42,43,44].map(x=>`<option ${String(x)===filterState.size?'selected':''}>${x}</option>`).join('')}</select><h4>PRICE</h4><select aria-label="Filter by price" onchange="filterState.price=this.value;rerender()"><option value="All">All prices</option><option value="under" ${filterState.price==='under'?'selected':''}>Under Rs. 3,000</option></select><button class="text-link" onclick="resetFilters()">Clear all filters</button></aside><div>${list.length?`<div class="grid shop-grid">${list.map(card).join('')}</div>`:'<div class="empty">No pairs match just yet.<br><br><button class="btn light" onclick="resetFilters()">Clear filters</button></div>'}</div></div></div><div style="height:60px"></div>`}
function resetFilters(){filterState={condition:'All',size:'All',price:'All'};rerender()}function rerender(){let y=scrollY;render(false);scrollTo(0,y)}
function detail(id){let p=products.find(x=>x.id===Number(id));if(!p)return '<div class="empty">This pair could not be found. <a href="#shop">Explore the edit</a></div>';selected=null;return `<div class="wrap"><div class="breadcrumb"><a href="#home">Home</a> / <a href="#shop/${p.category}">${p.category}</a> / ${p.name}</div><div class="product-detail"><div class="detail-image"><img src="assets/${p.img}.png" alt="${p.name}"></div><div class="detail-copy"><div class="eyebrow">${p.brand.toUpperCase()} · ${p.condition.toUpperCase()}</div><h1>${p.name}</h1><div class="price">${money(p.price)} <del>${money(p.old)}</del></div><p>A fresh chapter for an everyday favourite. A versatile ${p.color.toLowerCase()} ${p.type.toLowerCase()} pair, curated for your next adventure.</p><div class="callout">Sample product · Reference image. Actual photos, brand, size and condition will be updated with the store's inventory.</div><h4>${p.sizes.length?'SELECT YOUR SIZE — EU':'ONE SIZE'} <a class="text-link" href="#info/Size guide" style="float:right">Size guide ↗</a></h4>${p.sizes.length?`<div class="size-options">${p.sizes.map(s=>`<button onclick="selectSize(${s},this)">${s}</button>`).join('')}</div>`:'<div style="height:15px"></div>'}<div class="detail-actions"><button class="btn" onclick="add(${p.id})">Add to bag <span>↗</span></button><button class="btn light" onclick="toggleWish(${p.id},null)" aria-label="Save to wishlist">♡</button></div><button class="btn yellow full" onclick="if(add(${p.id},false))location.hash='checkout'">Buy now</button><p class="detail-note">✓ Quality checked inspiration &nbsp; · &nbsp; Guest checkout, always</p><details open><summary>Details & condition</summary><p>Colour: ${p.color}<br>Category: ${p.category} / ${p.type}<br>Condition: ${p.condition}<br>This preview uses sample inventory with a maximum of one per size.</p></details><details><summary>Delivery & returns</summary><p>Demo delivery charge: Rs. 250. Free demo shipping from Rs. 5,000. Final delivery and return policies will be provided by the store.</p></details></div></div><section class="section"><div class="section-head"><h2>A few more good finds.</h2><a class="text-link" href="#shop">View all ↗</a></div><div class="grid">${products.filter(x=>x.id!==p.id).slice(0,4).map(card).join('')}</div></section></div>`}
function selectSize(s,b){selected=s;document.querySelectorAll('.size-options button').forEach(x=>x.classList.remove('active'));b.classList.add('active')}
function quick(id){location.hash='product/'+id;toast('Choose your size to add this pair')}
function add(id,notify=true){let p=products.find(x=>x.id===id),s=p.sizes.length?selected:'One size';if(!s){toast('Please select your size first');return false}if(bag.some(x=>x.id===id&&x.size===s)){toast('This unique pair is already in your bag');return false}bag.push({id,size:s,qty:1});persist();if(notify){toast('Good find! Added to your bag');cart()}return true}
function openPanel(html){$('#panel').inert=false;lastFocus=document.activeElement;$('#panel').innerHTML=html;document.body.classList.add('panel-open');setTimeout(()=>$('#panel').querySelector('button,a,input')?.focus(),50)}function closePanel(){$('#panel').inert=true;document.body.classList.remove('panel-open');lastFocus?.focus()}
function panelHead(t){return `<div class="panel-head"><h2>${t}</h2><button class="close" onclick="closePanel()" aria-label="Close panel">×</button></div>`}
function cartItem(x,editable=true){let p=products.find(p=>p.id===x.id);return `<div class="cart-item"><img src="assets/${p.img}.png" alt="${p.name}"><div style="flex:1"><h3>${p.name}</h3><small>${x.size==='One size'?'One size':'EU '+x.size} · ${p.condition}</small><div style="margin-top:9px" class="price">${money(p.price)}</div>${editable?`<div class="quantity"><button onclick="removeItem(${p.id},'${x.size}')" aria-label="Remove one">−</button><span>1</span><button onclick="toast('Only one available for this size')" aria-label="Add one">+</button></div><button class="remove" onclick="removeItem(${p.id},'${x.size}')">Remove</button>`:''}</div></div>`}
function subtotal(){return bag.reduce((s,x)=>s+products.find(p=>p.id===x.id).price*x.qty,0)}function shipping(){return subtotal()>=5000?0:250}
function cart(){openPanel(panelHead(`Your bag (${bag.length})`)+(bag.length?bag.map(x=>cartItem(x)).join('')+`<div class="cart-total"><span>Subtotal</span><strong>${money(subtotal())}</strong></div><p style="font-size:11px;color:var(--muted)">${subtotal()>=5000?'Your demo shipping is on us.':'Demo shipping Rs. 250. Free from Rs. 5,000.'}</p><a class="btn full" href="#checkout" onclick="closePanel()">Guest checkout ↗</a><button class="text-link" style="display:block;margin:20px auto" onclick="closePanel()">Keep exploring</button>`:'<div class="empty">Your next great find is waiting.<br><br><a class="btn" href="#shop" onclick="closePanel()">Explore the edit ↗</a></div>'))}
function removeItem(id,s){bag=bag.filter(x=>!(x.id===id&&String(x.size)===s));persist();cart()}
function menu(){openPanel(panelHead('Explore the edit')+`<div class="menu-tabs"><button onclick="go('shop')">♧<br>Shoes</button><button onclick="go('info/Clothing')">♧<br>Clothing</button><button onclick="go('shop/Accessories')">♧<br>Accessories</button></div><a class="menu-link" href="#shop/Sale" onclick="closePanel()">The sale edit <span style="float:right;color:#9eac00">SALE</span></a><a class="menu-link" href="#shop" onclick="closePanel()">New arrivals ↗</a>${['Men','Women','Kids'].map(n=>`<details><summary>${n}</summary><a href="#shop/${n}" onclick="closePanel()">Shop all ${n.toLowerCase()}</a>${['Sports','Casual','Boots','Orthopedic'].map(t=>`<a href="#search/${n}%20${t}" onclick="closePanel()">${t}</a>`).join('')}</details>`).join('')}${['Sports','Casual','Accessories','Boots','Orthopedic'].map(n=>`<a class="menu-link" href="#shop/${n}" onclick="closePanel()">${n} ↗</a>`).join('')}<a class="menu-link" href="#wishlist" onclick="closePanel()">♡ Wishlist</a><a class="menu-link" href="#info/Condition guide" onclick="closePanel()">Condition guide</a><a class="menu-link" href="#info/Shipping & returns" onclick="closePanel()">Delivery & returns</a><a class="menu-link" href="#track" onclick="closePanel()">Track demo order</a>`)}
function go(r){closePanel();location.hash=r}function search(q){filterState={condition:'All',size:'All',price:'All'};location.hash='search/'+encodeURIComponent(q.trim());}function showWishlist(){location.hash='wishlist'}
function checkout(){if(!bag.length)return '<div class="empty"><h2>Your bag is empty.</h2><a href="#shop" class="btn">Find your pair ↗</a></div>';return `<div class="checkout"><form onsubmit="placeOrder(event)"><div class="eyebrow">NO ACCOUNT NEEDED</div><h1 style="margin-top:15px">Make them yours.</h1><div class="callout">This is a frontend demo. No real order or payment will be sent. Please use sample contact details.</div><h3>Delivery details</h3><label for="name">Full name *</label><input id="name" name="name" required maxlength="100" autocomplete="name"><div class="fields"><div><label for="email">Email *</label><input id="email" name="email" type="email" required autocomplete="email"></div><div><label for="phone">Phone *</label><input id="phone" name="phone" type="tel" required pattern="[+0-9 ()-]{10,18}" title="Enter a valid phone number (10–18 characters)" autocomplete="tel"></div></div><label for="address">Street address *</label><input id="address" name="address" required autocomplete="street-address"><label for="address2">Apartment, suite, etc. (optional)</label><input id="address2" name="address2"><div class="fields"><div><label for="city">City *</label><input id="city" name="city" required autocomplete="address-level2"></div><div><label for="province">Province / territory *</label><select id="province" name="province" required><option value="">Select</option>${['Sindh','Punjab','Khyber Pakhtunkhwa','Balochistan','Islamabad','Gilgit-Baltistan','Azad Kashmir'].map(x=>`<option>${x}</option>`).join('')}</select></div></div><label for="postal">Postal code *</label><input id="postal" name="postal" required pattern="[0-9]{5}" title="Enter a 5-digit postal code" autocomplete="postal-code"><label for="notes">Order notes (optional)</label><textarea id="notes" name="notes" rows="3"></textarea><h3 style="margin-top:30px">Payment</h3><div class="callout">◉ Cash on Delivery — demo only<br>No payment details are collected.</div><button class="btn full">Place demo order · ${money(subtotal()+shipping())} ↗</button></form><div class="order-box"><h3>Your good finds</h3>${bag.map(x=>cartItem(x,false)).join('')}<div class="summary-line"><span>Subtotal</span><span>${money(subtotal())}</span></div><div class="summary-line"><span>Demo delivery</span><span>${shipping()?money(shipping()):'On us'}</span></div><div class="cart-total"><span>Total</span><strong>${money(subtotal()+shipping())}</strong></div><p class="demo-note">Prices in PKR · Sample inventory</p></div></div>`}
function placeOrder(e){e.preventDefault();let f=new FormData(e.target);let order={ref:'SE-'+Date.now().toString(36).toUpperCase(),name:f.get('name'),items:[...bag],total:subtotal()+shipping(),date:new Date().toISOString()};orders.push(order);localStorage.setItem('se-orders',JSON.stringify(orders));bag=[];persist();location.hash='order/'+order.ref}
function orderPage(ref){let o=orders.find(x=>x.ref===ref);if(!o)return '<div class="empty">Demo order not found on this browser.</div>';return `<div class="info-page"><div class="success-icon">✓</div><div class="eyebrow">DEMO ORDER CREATED</div><h1 style="margin-top:20px">A great find, ${esc(o.name.split(' ')[0])}.</h1><p>Reference <strong>${esc(o.ref)}</strong><br>Your sample order is saved in this browser. It has not been sent to a seller and no payment has been taken.</p><div class="order-box">${o.items.map(x=>cartItem(x,false)).join('')}<div class="cart-total"><span>Total</span><strong>${money(o.total)}</strong></div></div><a href="#shop" class="btn" style="margin-top:25px">Keep exploring ↗</a></div>`}
function track(){return `<div class="info-page"><div class="eyebrow">YOUR NEXT CHAPTER</div><h1 style="margin-top:20px">Find your demo order.</h1><p>Enter a reference created in this browser. Live courier tracking is not connected.</p><form onsubmit="event.preventDefault();trackOrder(this.ref.value)"><input class="track-input" name="ref" placeholder="SE-…" required aria-label="Demo order reference"><button class="btn" style="margin-top:15px">Look up order ↗</button></form><div id="track-result"></div></div>`}function trackOrder(ref){let o=orders.find(x=>x.ref===ref.trim().toUpperCase());if(o)location.hash='order/'+o.ref;else $('#track-result').innerHTML='<p style="margin-top:25px">No matching demo order in this browser. Check the reference and try again.</p>'}
function info(t){let content={
'Our story':'<p>We believe a good pair deserves another chapter. Sole Edit is a concept store for carefully selected pre-loved footwear: everyday favourites, unexpected finds and a lighter way to shop.</p><p>This is a store preview. The final store name, inventory and business details can be updated before launch.</p>',
'Contact':'<p>Store contact details are being set up. A verified email address, WhatsApp number and store address can be added here before launch.</p><a class="btn" href="#info/FAQs">Browse FAQs ↗</a>',
'Clothing':'<p>The clothing collection is coming soon. Explore the footwear and accessories edit while we get it ready.</p><a class="btn" href="#shop">Shop the current edit ↗</a>',
'Size guide':'<p>Check the size on your best-fitting pair and compare it with the product’s EU size. Sizing varies by brand; measurements should be checked before a real purchase.</p><table><tr><th>EU</th><th>Approx. UK</th><th>Approx. foot length</th></tr>'+[[37,4,'23.5 cm'],[38,5,'24 cm'],[39,6,'24.5 cm'],[40,6.5,'25 cm'],[41,7,'26 cm'],[42,8,'26.5 cm'],[43,9,'27.5 cm'],[44,10,'28 cm']].map(x=>'<tr>'+x.map(v=>`<td>${v}</td>`).join('')+'</tr>').join('')+'</table><p>Indicative adult conversions only. Kids’ sizing and brand-specific measurements must be confirmed separately.</p>',
'Condition guide':'<p><strong>New</strong> — unused sample inventory.</p><p><strong>Excellent</strong> — a pre-loved pair with light signs of wear.</p><p><strong>Very good</strong> — visible signs of wear, with plenty of life left.</p><p>These are sample condition labels. Actual product photos and individual condition notes must be provided for real stock.</p>',
'Shipping & returns':'<p>This preview calculates a sample delivery fee of Rs. 250, with free demo delivery on orders of Rs. 5,000 or more.</p><p>Orders placed here are browser-local demos. Real shipping coverage, delivery estimates, return eligibility and refund terms will be added by the store before real orders are accepted.</p>',
'FAQs':'<details open><summary>Are these real products available to order?</summary><p>This is a frontend preview using sample inventory and reference images. Demo orders do not reach a seller.</p></details><details><summary>Do I need an account?</summary><p>No. Browse, save favourites and use guest checkout without logging in.</p></details><details><summary>Where is my cart saved?</summary><p>Your bag, wishlist and demo orders stay in this browser. Clearing browser storage removes them.</p></details><details><summary>Can I buy more than one pair?</summary><p>You can add different products and sizes. Each sample size has a quantity limit of one, as is common with unique pre-loved stock.</p></details>'};return `<div class="info-page"><div class="eyebrow">A LITTLE HELP, EVERY STEP</div><h1 style="margin-top:20px">${esc(t)}.</h1>${content[t]||'<p>This collection is being prepared.</p>'}</div>`}
function render(scroll=true){let [route,arg]=location.hash.slice(1).split('/');arg=decodeURIComponent(arg||'');closePanel();if(route==='shop')$('#app').innerHTML=collection(arg||'All');else if(route==='search')$('#app').innerHTML=collection('All',arg);else if(route==='product')$('#app').innerHTML=detail(arg);else if(route==='checkout')$('#app').innerHTML=checkout();else if(route==='info')$('#app').innerHTML=info(arg);else if(route==='order')$('#app').innerHTML=orderPage(arg);else if(route==='track')$('#app').innerHTML=track();else if(route==='wishlist')$('#app').innerHTML=`<div class="wrap"><div class="collection-header" style="padding-top:45px"><div class="eyebrow">SAVED FOR ANOTHER STEP</div><h1 style="margin-top:15px">Your good finds.</h1><p>${wish.length} saved favourites</p></div>${wish.length?`<div class="grid">${products.filter(p=>wish.includes(p.id)).map(card).join('')}</div>`:'<div class="empty">Nothing saved yet. Tap ♡ on a pair you love.<br><br><a href="#shop" class="btn">Find your favourite ↗</a></div>'}</div>`;else $('#app').innerHTML=home();if(scroll)scrollTo(0,0);persist()}
window.addEventListener('hashchange',()=>{filterState={condition:'All',size:'All',price:'All'};render()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closePanel();if(e.key==='Tab'&&document.body.classList.contains('panel-open')){let els=[...$('#panel').querySelectorAll('a[href],button,input,select,summary')].filter(el=>el.getClientRects().length),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});render();
